#[cfg(test)]
mod test {
    use pretty_assertions::assert_eq;

    use super::{
        GpuFacts, LicenseSection, RegionFacts, SessionFacts, SupportInfo, SystemFacts,
        parse_license_sections, support_block,
    };

    /// A fully-populated info renders every group in stable order.
    #[test]
    fn support_block_full() {
        let info = SupportInfo {
            viewer_name: "sl-client-bevy-viewer".to_owned(),
            viewer_version: "0.1.0+abc1234".to_owned(),
            build_profile: "release".to_owned(),
            bevy_version: Some("0.19.0".to_owned()),
            wgpu_version: Some("26.0.1".to_owned()),
            session: Some(SessionFacts {
                grid: "localhost".to_owned(),
                login_uri: "http://127.0.0.1:9000/".to_owned(),
                channel: "sl-client-bevy-viewer 0.1.0+abc1234".to_owned(),
            }),
            region: Some(RegionFacts {
                name: Some("Default Region".to_owned()),
                coordinates: (1000, 1000),
                product_name: "Mainland".to_owned(),
                product_sku: "023".to_owned(),
            }),
            sim_host: Some("127.0.0.1:9001".to_owned()),
            simulator_version: Some("OpenSim 0.9.3.1 Yeti Dev".to_owned()),
            system: Some(SystemFacts {
                os: "Gentoo Linux".to_owned(),
                kernel: "6.12.1".to_owned(),
                cpu: "AMD Ryzen 9".to_owned(),
                core_count: "32".to_owned(),
                memory: "64.0 GiB".to_owned(),
            }),
            gpu: Some(GpuFacts {
                name: "AMD Radeon RX 7900 XTX".to_owned(),
                device_type: "DiscreteGpu".to_owned(),
                backend: "Vulkan".to_owned(),
                driver: "radv".to_owned(),
                driver_info: "Mesa 25.0.1".to_owned(),
            }),
            window_size: Some((2560, 1440)),
            ui_language: Some("en".to_owned()),
        };
        assert_eq!(
            support_block(&info),
            "sl-client-bevy-viewer 0.1.0+abc1234 (release build)\n\
             Bevy 0.19.0, wgpu 26.0.1\n\
             \n\
             Grid: localhost (http://127.0.0.1:9000/)\n\
             Login channel: sl-client-bevy-viewer 0.1.0+abc1234\n\
             Region: Default Region (1000, 1000)\n\
             Product: Mainland (023)\n\
             Simulator host: 127.0.0.1:9001\n\
             Simulator version: OpenSim 0.9.3.1 Yeti Dev\n\
             \n\
             OS: Gentoo Linux\n\
             Kernel: 6.12.1\n\
             CPU: AMD Ryzen 9 (32 cores)\n\
             Memory: 64.0 GiB\n\
             GPU: AMD Radeon RX 7900 XTX (DiscreteGpu)\n\
             GPU driver: radv Mesa 25.0.1\n\
             Graphics backend: Vulkan\n\
             Window size: 2560x1440\n\
             UI language: en"
        );
    }

    /// With nothing session-derived available the block still renders — the
    /// grid line says not connected, optional lines are omitted, and there is
    /// no trailing whitespace.
    #[test]
    fn support_block_not_connected() {
        let info = SupportInfo {
            viewer_name: "sl-client-bevy-viewer".to_owned(),
            viewer_version: "0.1.0".to_owned(),
            build_profile: "debug".to_owned(),
            ..SupportInfo::default()
        };
        let block = support_block(&info);
        assert_eq!(
            block,
            "sl-client-bevy-viewer 0.1.0 (debug build)\n\
             \n\
             Grid: (not connected)"
        );
        assert!(
            block.lines().all(|line| line.trim_end() == line),
            "no line may carry trailing whitespace: {block:?}"
        );
    }

    /// The generated-file format round-trips: preamble skipped, id / name /
    /// used-by / text captured per section.
    #[test]
    fn parse_license_sections_sample() {
        let sample = "Third-party licenses.\n\
                      Generated file preamble.\n\
                      \n\
                      === LICENSE Apache-2.0 === Apache License 2.0 ===\n\
                      used-by: foo 1.0.0, bar 2.1.3\n\
                      \n\
                      Apache License\n\
                      Version 2.0, January 2004\n\
                      \n\
                      === LICENSE MIT === MIT License ===\n\
                      used-by: baz 0.3.0\n\
                      \n\
                      MIT License text.\n";
        assert_eq!(
            parse_license_sections(sample),
            vec![
                LicenseSection {
                    id: "Apache-2.0".to_owned(),
                    name: "Apache License 2.0".to_owned(),
                    used_by: "foo 1.0.0, bar 2.1.3".to_owned(),
                    text: "Apache License\nVersion 2.0, January 2004".to_owned(),
                },
                LicenseSection {
                    id: "MIT".to_owned(),
                    name: "MIT License".to_owned(),
                    used_by: "baz 0.3.0".to_owned(),
                    text: "MIT License text.".to_owned(),
                },
            ]
        );
    }
}
